body:
I just was pointing them out, I didn't plan to make any changes without profiling them first.
I did some tests locally to check which way is faster for both `TypedArray` and `Vector`.

**TypedArray**:
```c++
	Vector<Vector4> vec_from;
	vec_from.resize(10000000);
	int time = 0;

	{
		time = Time::get_singleton()->get_ticks_msec();
		TypedArray<Vector4> vec_to;
		for (int i = 0; i < vec_from.size(); i++) {
			vec_to.push_back(vec_from[i]);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 4294 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		TypedArray<Vector4> vec_to;
		vec_to.resize(vec_from.size());
		for (int i = 0; i < vec_from.size(); i++) {
			vec_to.set(i, vec_from[i]);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 3478 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		TypedArray<Vector4> vec_to;
		const int size = vec_from.size();
		vec_to.resize(size);
		for (int i = 0; i < size; i++) {
			vec_to.set(i, vec_from[i]);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 3336 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		TypedArray<Vector4> vec_to;
		const int size = vec_from.size();
		vec_to.resize(size);
		for (int i = 0; i < size; i++) {
			vec_to[i] = vec_from[i];
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 2651 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		TypedArray<Vector4> vec_to;
		vec_to.resize(vec_from.size());
		int idx = 0;
		for (const Vector4 &E : vec_from) {
			vec_to.set(idx++, E);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 3249 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		TypedArray<Vector4> vec_to;
		vec_to.resize(vec_from.size());
		int idx = 0;
		for (const Vector4 &E : vec_from) {
			vec_to[idx++] = E;
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 2557 ms
```

**Vector**:

```c++
	Vector<Vector4> vec_from;
	vec_from.resize(10000000);
	int time = 0;

	{
		time = Time::get_singleton()->get_ticks_msec();
		PackedVector4Array vec_to;
		for (int i = 0; i < vec_from.size(); i++) {
			vec_to.push_back(vec_from[i]);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 2884 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		PackedVector4Array vec_to;
		vec_to.resize(vec_from.size());
		for (int i = 0; i < vec_from.size(); i++) {
			vec_to.set(i, vec_from[i]);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 1335 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		PackedVector4Array vec_to;
		const int size = vec_from.size();
		vec_to.resize(size);
		for (int i = 0; i < size; i++) {
			vec_to.set(i, vec_from[i]);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 1194 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		PackedVector4Array vec_to;
		const int size = vec_from.size();
		vec_to.resize(size);
		for (int i = 0; i < size; i++) {
			vec_to.write[i] = vec_from.write[i];
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 1749 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		PackedVector4Array vec_to;
		vec_to.resize(vec_from.size());
		int idx = 0;
		for (const Vector4 &E : vec_from) {
			vec_to.set(idx++, E);
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 1102 ms

	{
		time = Time::get_singleton()->get_ticks_msec();
		PackedVector4Array vec_to;
		vec_to.resize(vec_from.size());
		int idx = 0;
		for (const Vector4 &E : vec_from) {
			vec_to.write[idx++] = E;
		}
		print_line(Time::get_singleton()->get_ticks_msec() - time);
	} // Time: 1063 ms
```
